import sys
sys.setrecursionlimit(100000)

# ---------- types ----------
# ('v', n) | ('a', A, B)  (arrow) | ('l', A)  (forall)
def V(n): return ('v', n)
def Arr(a,b): return ('a',a,b)
def All(a): return ('l',a)

def size(t):
    k=t[0]
    if k=='v': return 1
    if k=='a': return 1+size(t[1])+size(t[2])
    return 1+size(t[1])

def ren(xi, t):
    k=t[0]
    if k=='v': return ('v', xi(t[1]))
    if k=='a': return ('a', ren(xi,t[1]), ren(xi,t[2]))
    # all: scons 0 (S . xi)
    return ('l', ren(lambda n: 0 if n==0 else xi(n-1)+1, t[1]))

def subst(sig, t):
    k=t[0]
    if k=='v': return sig(t[1])
    if k=='a': return ('a', subst(sig,t[1]), subst(sig,t[2]))
    # all: scons (Var0) (ren S . sig)
    return ('l', subst(lambda n: V(0) if n==0 else ren(lambda m:m+1, sig(n-1)), t[1]))

def scons(x, xi): return lambda n: x if n==0 else xi(n-1)
def shift(t): return ren(lambda n:n+1, t)

def show(t):
    k=t[0]
    if k=='v': return chr(ord('a')+t[1]) if t[1]<26 else f"v{t[1]}"
    if k=='a': return "("+show(t[1])+"->"+show(t[2])+")"
    return "(/α."+show(t[1])+")"

# ---------- terms ----------
def Var(n): return ('v',n)
def App(m,n): return ('@',m,n)
def Abs(m): return ('\\',m)
def tsize(m):
    k=m[0]
    if k=='v': return 1
    if k=='@': return 1+tsize(m[1])+tsize(m[2])
    return 1+tsize(m[1])
def tshow(m):
    k=m[0]
    if k=='v': return f"x{m[1]}"
    if k=='@': return f"({tshow(m[1])} {tshow(m[2])})"
    return f"(\\x.{tshow(m[1])})"

# ---------- type pool ----------
def gen_types(vmax, smax):
    # all types with vars in 0..vmax-1 (as free leaves) and size <= smax
    bysize={1:[V(i) for i in range(vmax)]}
    alltypes=[t for t in bysize[1]]
    for s in range(2, smax+1):
        cur=[]
        for a in range(1,s-1):
            b=s-1-a
            if b<1: continue
            for x in bysize.get(a,[]):
                for y in bysize.get(b,[]):
                    cur.append(('a',x,y))
        # all with body size s-1
        for x in bysize.get(s-1,[]):
            cur.append(('l',x))
        bysize[s]=cur
        alltypes.extend(cur)
    return alltypes, bysize

# environment: tuple of types (index 0 first)
def nth(env, x):
    return env[x] if 0<=x<len(env) else None

def shift_env(env):
    return tuple(shift(t) for t in env)

# ---------- search ----------
class Searcher:
    def __init__(self, vmax, smax):
        self.pool, self.bysize = gen_types(vmax, smax)
        # precompute inst pairs: (s', u) -> result type
        self.inst_pairs=[]
        for sp in self.pool:
            for u in self.pool:
                r = subst(scons(u, lambda n: V(n)), sp)
                self.inst_pairs.append((sp,u,r))
        self.inst_by_result={}
        for sp,u,r in self.inst_pairs:
            self.inst_by_result.setdefault(r,[]).append((sp,u))
        # env-type choices are pool
        self.envpool=self.pool
        self.calls=0
        self.memo=None
        self.fuel=0

    def search(self, env, M, t, fuel, path):
        # returns derivation list or None; exact fuel not required, just bound
        self.calls+=1
        if fuel<=0: return None
        key=(env,M,t)
        st=self.memo.get(key)
        if st is not None and st>=fuel:
            return None  # already failed with at least this fuel
        k=M[0]
        results=[]
        def try_goal(env2,M2,t2,f2):
            r=self.search(env2,M2,t2,f2,path)
            if r is not None:
                results.append(( ('goal',env2,M2,t2), r))
                return True
            return False

        # rules by term shape
        if k=='v':
            x=M[1]
            s=nth(env,x)
            if s==t:
                self._mark(key,fuel)
                return [('var',x,s)]
        if k=='@':
            m,n=M[1],M[2]
            # try app: middle from pool (smaller first)
            for s in self.pool:
                r1=self.search(env,m,Arr(s,t),fuel-1,path)
                if r1 is not None:
                    r2=self.search(env,n,s,fuel-1,path)
                    if r2 is not None:
                        self._mark(key,fuel)
                        return [('app',s,r1,r2)]
        if k=='\\':
            m=M[1]
            if t[0]=='a':
                s,u=t[1],t[2]
                # choose environment scheme from pool (but s is forced = t[1]); abs forces that
                r=self.search((s,)+env,m,u,fuel-1,path)
                if r is not None:
                    self._mark(key,fuel)
                    return [('abs',s,u,r)]
        # gen rule (any term): t = All u ; premise in shifted env
        if t[0]=='l':
            u=t[1]
            r=self.search(shift_env(env),M,u,fuel-1,path)
            if r is not None:
                self._mark(key,fuel)
                return [('gen',u,r)]
        # inst rule (any term): t instance of sp
        for sp,uu in self.inst_by_result.get(t,[]):
            r=self.search(env,M,All(sp),fuel-1,path)
            if r is not None:
                self._mark(key,fuel)
                return [('inst',sp,uu,r)]
        self._mark(key,fuel)
        return None

    def _mark(self,key,fuel):
        old=self.memo.get(key)
        if old is None or fuel>old:
            self.memo[key]=fuel

    def typable(self, M, maxfuel, roots=None):
        self.memo={}
        roots=self.pool if roots is None else roots
        for f in range(1,maxfuel+1):
            self.memo={}
            for t in roots:
                self.calls=0
                r=self.search((), M, t, f, [])
                if r is not None:
                    return t,r,self.calls
        return None

def pp(t,r,indent=0):
    sp='  '*indent
    tag=r[0]
    if tag=='var':
        return sp+f"var x{r[1]} : {show(r[2])}"
    if tag=='abs':
        return sp+f"abs {show(r[1])} -> {show(r[2])}\n"+pp(r[1],r[3],indent+1) if False else sp+f"abs arg={show(r[1])} cod={show(r[2])}\n"+pp(None,r[3],indent+1)
    if tag=='app':
        return sp+f"app middle={show(r[1])}\n"+pp(None,r[2],indent+1)+"\n"+pp(None,r[3],indent+1)
    if tag=='gen':
        return sp+f"gen body={show(r[1])}\n"+pp(None,r[2],indent+1)
    if tag=='inst':
        return sp+f"inst scheme={show(r[1])} at={show(r[2])}\n"+pp(None,r[3],indent+1)
    return sp+str(r)

if __name__=='__main__':
    # quick sanity: check subst/ren examples
    bottom=All(V(0))
    print("bottom:",show(bottom))
    print("inst bottom at Arr(a,b):",show(subst(scons(Arr(V(0),V(1)),lambda n:V(n)),V(0))))
    print("ren S bottom:",show(shift(bottom)))
    # xx = \x. x x
    xx=Abs(App(Var(0),Var(0)))
    print("term:",tshow(xx))

