    # returns derivation list or None; fuel is a bound on derivation steps
    self.calls+=1
    if fuel<=0: return None
    key=(env,M,t)
    st=self.memo.get(key)
    if st is not None and st>=fuel:
        return None  # already failed with at least this fuel
    k=M[0]

    # var base
    if k=='v':
        x=M[1]
        s=nth(env,x)
        if s==t:
            return [('var',x,s)]
    # app rule
    if k=='@':
        m,n=M[1],M[2]
        for s in self.pool:
            r1=self.search(env,m,Arr(s,t),fuel-1,path)
            if r1 is not None:
                r2=self.search(env,n,s,fuel-1,path)
                if r2 is not None:
                    return [('app',s,r1,r2)]
    # abs rule
    if k=='\\':
        m=M[1]
        if t[0]=='a':
            s,u=t[1],t[2]
            r=self.search((s,)+env,m,u,fuel-1,path)
            if r is not None:
                return [('abs',s,u,r)]
    # gen rule (any term): t = All u ; premise in shifted env
    if t[0]=='l':
        u=t[1]
        r=self.search(shift_env(env),M,u,fuel-1,path)
        if r is not None:
            return [('gen',u,r)]
    # inst rule (any term): t is an instance of All sp
    for sp,uu in self.inst_by_result.get(t,[]):
        r=self.search(env,M,All(sp),fuel-1,path)
        if r is not None:
            return [('inst',sp,uu,r)]
    # failure: remember max fuel that failed
    old=self.memo.get(key)
    if old is None or fuel>old:
        self.memo[key]=fuel
    return None

