import itertools, sys
from functools import lru_cache

# terms as tuples: ('a',n) atom | ('r',x,y) arr
def size(t): return 1 if t[0]=='a' else 1+size(t[1])+size(t[2])
def atoms(t,s=None):
    if s is None: s=set()
    if t[0]=='a': s.add(t[1])
    else: atoms(t[1],s); atoms(t[2],s)
    return s
def subst(f,t):
    return f[t[1]] if t[0]=='a' else ('r',subst(f,t[1]),subst(f,t[2]))

def gen_terms(natoms, maxsize):
    # all terms over atoms 0..natoms-1 with size<=maxsize
    bysize={1:[('a',i) for i in range(natoms)]}
    allt=list(bysize[1])
    for sz in range(2,maxsize+1):
        cur=[]
        for s1 in range(1,sz-1):
            s2=sz-1-s1
            if s1 in bysize and s2 in bysize:
                for x in bysize[s1]:
                    for y in bysize[s2]:
                        cur.append(('r',x,y))
        bysize[sz]=cur
        allt+=cur
    return bysize, allt

# For a problem (s,t0,t1) over atoms A, substitutions only need to be defined on A
# (plus atoms introduced in images? psi acts on atoms appearing in phi(s), which may
#  include atoms outside A because phi images can contain arbitrary atoms. Use same atom universe.)
def original_solvable(s,t0,t1, subterms, natoms):
    # enumerate phi, psi0, psi1 over natoms
    # optimize: phi images from subterms; psi images from subterms
    subs=[]
    # all maps natoms -> terms (cartesian)
    for imgs in itertools.product(subterms, repeat=natoms):
        subs.append(imgs)
    for phi in subs:
        ps=subst(phi,s)
        # need psi_i with psi_i(ps)=phi(t_i)
        for i,ti in ((0,t0),(1,t1)):
            ti_phi=subst(phi,ti)
            found=False
            for psi in subs:
                if subst(psi,ps)==ti_phi:
                    found=True;break
            if not found:
                break
        else:
            return True
    return False

def ordinary_solvable(s,t0,t1, subterms, natoms):
    for phi in itertools.product(subterms, repeat=natoms):
        ok=True
        for ti in (t0,t1):
            ti_phi=subst(phi,ti)
            found=False
            for rho in itertools.product(subterms, repeat=natoms):
                if subst(rho,s)==ti_phi:
                    found=True;break
            if not found: ok=False;break
        if ok: return True
    return False

if __name__=='__main__':
    natoms=2
    bysize,allt=gen_terms(natoms,4)
    print("num terms",len(allt))
    probterms=[t for t in allt if 1<=size(t)<=3]
    subterms=allt
    count=0
    for s in probterms:
        for t0 in probterms:
            for t1 in probterms:
                o=ordinary_solvable(s,t0,t1,subterms,natoms)
                if o:
                    orig=original_solvable(s,t0,t1,subterms,natoms)
                    if not orig:
                        print("STRICT CANDIDATE",s,t0,t1)
                        sys.exit()
                count+=1
    print("no strict candidate among",count)
