import itertools, sys

# semi-unif terms: ('n',i) atom | ('r',a,b) arr
def N(i): return ('n',i)
def R(a,b): return ('r',a,b)
def ssize(t):
    return 1 if t[0]=='n' else 1+ssize(t[1])+ssize(t[2])
def sshow(t):
    return f"{t[1]}" if t[0]=='n' else f"({sshow(t[1])} {sshow(t[2])})"

def subst(f, t):
    if t[0]=='n': return f(t[1])
    return R(subst(f,t[1]), subst(f,t[2]))

def atoms(t, acc=None):
    if acc is None: acc=set()
    if t[0]=='n': acc.add(t[1])
    else: atoms(t[1],acc); atoms(t[2],acc)
    return acc

def terms_upto(maxsize, natoms):
    bys={1:[N(i) for i in range(natoms)]}
    allt=list(bys[1])
    for s in range(2,maxsize+1):
        cur=[]
        for a in range(1,s-1):
            b=s-1-a
            if b<1: continue
            for x in bys.get(a,[]):
                for y in bys.get(b,[]):
                    cur.append(R(x,y))
        bys[s]=cur
        allt.extend(cur)
    return allt, bys

def match(pattern, target, mp):
    # one-sided matching: pattern atoms are variables; target ground (atoms constants)
    # mp dict reused; returns True/False, mutating mp (need backtracking -> we copy)
    if pattern[0]=='n':
        a=pattern[1]
        if a in mp: return mp[a]==target
        mp[a]=target; return True
    if target[0]!='r': return False
    return match(pattern[1],target[1],mp) and match(pattern[2],target[2],mp)

def matches(pattern, target):
    return match(pattern,target,{})

def solvable(s,t0,t1,maxsize=5,natoms=2,depth=3):
    """search phi: domain atoms -> terms with size <= maxsize over natoms; iterative deepening handled by caller"""
    D=sorted(atoms(s)|atoms(t0)|atoms(t1))
    vals,_=terms_upto(maxsize,natoms)
    # restrict phi values that use atoms: all vals fine
    for combo in itertools.product(vals, repeat=len(D)):
        ph=dict(zip(D,combo))
        f=lambda n: ph[n]
        X=subst(f,s); R0=subst(f,t0); R1=subst(f,t1)
        if matches(X,R0) and matches(X,R1):
            return ph, X, R0, R1
    return None

def solvable_iter(s,t0,t1,maxsize=6,natoms=2):
    for m in range(1,maxsize+1):
        # only iterate by max value size; need enough values
        r=solvable(s,t0,t1,m,natoms)
        if r is not None: return r,m
    return None,None

if __name__=='__main__':
    tests=[
      (N(0), R(N(0),N(0)), N(0)),
      (R(N(0),N(0)), N(0), N(0)),
      (N(0), R(N(0),N(1)), N(1)),
      (R(N(0),N(1)), R(N(0),N(0)), N(1)),
      (N(0), N(1), N(0)),
      (R(N(0),N(0)), R(N(0),N(0)), N(0)),
    ]
    for (s,a,b) in tests:
        r,m=solvable_iter(s,a,b,5,2)
        if r: print(sshow(s),'|',sshow(a),'|',sshow(b),'SOLVABLE m=',m,'phi=',r[0],'X=',sshow(r[1]))
        else: print(sshow(s),'|',sshow(a),'|',sshow(b),'unsolvable(bounds)')

