import itertools, sys
from functools import lru_cache

def size(t): return 1 if t[0]=='a' else 1+size(t[1])+size(t[2])
def atoms_of(t,s):
    if t[0]=='a': s.add(t[1])
    else: atoms_of(t[1],s); atoms_of(t[2],s)
    return s
def subst(f,t):
    return f[t[1]] if t[0]=='a' else ('r',subst(f,t[1]),subst(f,t[2]))

def match(pat, tgt, sub):
    # pat variables are atom indices; match pat to tgt, extend sub dict; return bool
    if pat[0]=='a':
        n=pat[1]
        if n in sub: return sub[n]==tgt
        sub[n]=tgt; return True
    else:
        if tgt[0]!='r': return False
        return match(pat[1],tgt[1],sub) and match(pat[2],tgt[2],sub)

def is_instance(pat,tgt):
    return match(pat,tgt,{})

def gen_terms(natoms, maxsize):
    bysize={1:[('a',i) for i in range(natoms)]}
    allt=list(bysize[1])
    for sz in range(2,maxsize+1):
        cur=[]
        for s1 in range(1,sz-1):
            s2=sz-1-s1
            if s1 in bysize and s2 in bysize:
                for x in bysize[s1]:
                    for y in bysize[s2]:
                        cur.append(('r',x,y))
        bysize[sz]=cur; allt+=cur
    return bysize,allt

def check(s,t0,t1, subterms, natoms):
    # returns (ordinary,original) with phi images enumerated
    ord_ok=False; orig_ok=False
    for phi_imgs in itertools.product(subterms, repeat=natoms):
        phi={i:phi_imgs[i] for i in range(natoms)}
        t0p=subst(phi,t0); t1p=subst(phi,t1)
        # ordinary: is t0p instance of s and t1p instance of s
        if not ord_ok and is_instance(s,t0p) and is_instance(s,t1p):
            ord_ok=True
        if not orig_ok:
            sp=subst(phi,s)
            if is_instance(sp,t0p) and is_instance(sp,t1p):
                orig_ok=True
        if ord_ok and orig_ok: return True,True
    return ord_ok,orig_ok

if __name__=='__main__':
    natoms=int(sys.argv[1]) if len(sys.argv)>1 else 3
    maxsz=int(sys.argv[2]) if len(sys.argv)>2 else 4
    bysize,allt=gen_terms(natoms,maxsz)
    probterms=[t for t in allt if size(t)<=3]
    print("natoms",natoms,"maxsz",maxsz,"probs",len(probterms),"subs",len(allt), file=sys.stderr)
    cnt=0
    for s in probterms:
        for t0 in probterms:
            for t1 in probterms:
                if t0==t1: continue  # require distinct inequalities
                o,orig=check(s,t0,t1,allt,natoms)
                if o and not orig:
                    print("STRICT CANDIDATE (distinct t):",s,t0,t1); sys.exit()
                cnt+=1
    print("no strict candidate among",cnt)
