import sys, itertools, time
sys.path.insert(0,'/tmp')
from semi import *

# all terms size <= 3 over atoms 0,1
def terms_size_le(k, natoms=2):
    out=[]
    for n in range(natoms): out.append(N(n))
    # only odd sizes
    for s in range(3,k+1,2):
        for a in range(1,s-1,2):
            b=s-1-a
            if b<1 or b%2==0: continue
            ta=[t for t in out if ssize(t)==a]
            tb=[t for t in out if ssize(t)==b]
            for x in ta:
                for y in tb: out.append(R(x,y))
    # dedupe preserve
    res=[]
    seen=set()
    for t in out:
        if t not in seen: seen.add(t); res.append(t)
    return res

def all_terms_exact(k,natoms=2):
    bys={}
    for n in range(natoms): bys.setdefault(1,[]).append(N(n))
    for s in range(3,k+1,2):
        cur=[]
        for a in range(1,s-1,2):
            b=s-1-a
            if b<1 or b%2==0: continue
            for x in bys.get(a,[]):
                for y in bys.get(b,[]): cur.append(R(x,y))
        bys[s]=cur
    out=[]
    for s in sorted(bys): out.extend(bys[s])
    return out

if __name__=='__main__':
    small=terms_size_le(3)
    print("small terms:",[sshow(t) for t in small])
    vals,_=terms_upto(5,2)
    print("num phi values size<=5:",len(vals))
    # fast solvable with fixed maxsize
    def solve(s,t0,t1,maxsize=5,natoms=2):
        D=sorted(atoms(s)|atoms(t0)|atoms(t1))
        vals,_=terms_upto(maxsize,natoms)
        for combo in itertools.product(vals, repeat=len(D)):
            ph=dict(zip(D,combo)); f=lambda n: ph[n]
            X=subst(f,s); R0=subst(f,t0); R1=subst(f,t1)
            if matches(X,R0) and matches(X,R1): return True
        return False
    t0=time.time(); res={}
    for s in small:
        for a in small:
            for b in small:
                res[(s,a,b)]=solve(s,a,b,5,2)
    print("done",time.time()-t0,"solvable count",sum(res.values()),"/",len(res))
    # show all triples (size<=3) solvable, grouped
    for t in small:
        pass
    import pickle
    with open('/tmp/gt_small.pkl','wb') as fh: pickle.dump((small,res),fh)
    for (s,a,b),v in res.items():
        if v: print("SOLV",sshow(s),'|',sshow(a),'|',sshow(b))

