import sys, itertools
sys.setrecursionlimit(1000000)

# ---------- type representation with named binders and logic metavars ----------
# ('m',id) | ('v',name) rigid | ('arr',a,b) | ('all',name,body)

class St:
    __slots__=('sub','nextm','nextn')
    def __init__(s, sub=None, nextm=0, nextn=0):
        s.sub = {} if sub is None else sub
        s.nextm=nextm; s.nextn=nextn
    def copy(s): return St(dict(s.sub), s.nextm, s.nextn)
    def freshm(s):
        i=s.nextm; s.nextm+=1; return ('m',i)
    def freshtv(s):
        i=s.nextn; s.nextn+=1; return ('v',f"a{i}")

def walk(t, sub):
    while t[0]=='m':
        v=sub.get(t[1])
        if v is None: break
        t=v
    return t

def occurs(mid, t, sub):
    t=walk(t,sub)
    if t[0]=='m': return t[1]==mid
    if t[0]=='v': return False
    if t[0]=='arr': return occurs(mid,t[1],sub) or occurs(mid,t[2],sub)
    return occurs(mid,t[3],sub)  # bound names irrelevant

def subst_tv(t, name, repl, sub):
    # capture-avoiding substitution of rigid tv 'name' (names globally unique => no capture)
    t=walk(t,sub)
    if t[0]=='m': return t
    if t[0]=='v': return repl if t[1]==name else t
    if t[0]=='arr': return ('arr', subst_tv(t[1],name,repl,sub), subst_tv(t[2],name,repl,sub))
    return ('all', t[1], subst_tv(t[3],name,repl,sub))

def unify(a,b,sub):
    a=walk(a,sub); b=walk(b,sub)
    if a==b: return True
    if a[0]=='m':
        if occurs(a[1],b,sub): return False
        sub[a[1]]=b; return True
    if b[0]=='m':
        if occurs(b[1],a,sub): return False
        sub[b[1]]=a; return True
    if a[0]=='arr' and b[0]=='arr':
        return unify(a[1],b[1],sub) and unify(a[2],b[2],sub)
    if a[0]=='all' and b[0]=='all':
        if a[1]==b[1]: return unify(a[3],b[3],sub)
        # rename b's binder to a's name in body
        body=subst_tv(b[3], b[1], ('v',a[1]), sub)
        return unify(a[3],body,sub)
    return False

def tshow(t, sub=None):
    if sub is not None: t=walk(t,sub)
    k=t[0]
    if k=='m': return f"?{t[1]}"
    if k=='v': return t[1]
    if k=='arr': return f"({tshow(t[1],sub)}->{tshow(t[2],sub)})"
    return f"(/ {t[1]}.{tshow(t[3],sub)})"

def free_names(t, sub):
    t=walk(t,sub)
    if t[0]=='m': return set()
    if t[0]=='v': return {t[1]}
    if t[0]=='arr': return free_names(t[1],sub)|free_names(t[2],sub)
    return free_names(t[3],sub)-{t[1]}

# ---------- terms ----------
def Var(n): return ('v',n)
def App(m,n): return ('@',m,n)
def Abs(m): return ('\\',m)
def tsz(m):
    return 1 if m[0]=='v' else (1+tsz(m[1])+tsz(m[2]) if m[0]=='@' else 1+tsz(m[1]))

class Infer:
    def __init__(self, Jmax=3):
        self.Jmax=Jmax
        self.nodes=0
        self.limit=200000

    # returns list of (type, sub) minimal: we return first found
    def synth(self, env, M, budget, st, depth=0):
        self.nodes+=1
        if self.nodes>self.limit: return None
        if budget<0: return None
        k=M[0]
        if k=='v':
            x=M[1]
            if x>=len(env):
                # free variable: wildcard type
                return (st.freshm(), st, budget)
            scheme=env[x]
            # choose number of instantiations j
            for j in range(0, min(budget, self.Jmax)+1):
                st2=st.copy()
                t,peeled=self.inst(scheme,j,st2)
                if peeled==j or True:
                    r=self.synth(env, ('v',x), budget-1, st2) if False else None
                    # direct: occurrence type t
                    # But we may also want to instantiate further later; t itself is fine.
                    return (t, st2, budget-j)
            return None
        if k=='\\':
            m=M[1]
            # choose n = number of foralls of the scheme
            for n in range(0, min(budget,self.Jmax)+1):
                st2=st.copy()
                names=[]
                for _ in range(n):
                    names.append(st2.freshtv()[1])
                beta=st2.freshm()
                scheme=beta
                for nm in reversed(names):
                    scheme=('all',nm,scheme)
                # scheme = All a1. All a2. ... beta  (beta not scope-aware; binder names global)
                r=self.synth((scheme,)+env, m, budget-n, st2, depth+1)
                if r is not None:
                    tb,st3,bu=r
                    return (('arr', scheme, tb), st3, bu)
            return None
        if k=='@':
            m,n=M[1],M[2]
            # split budget
            for b1 in range(0,budget+1):
                b2=budget-b1
                rM=self.synth(env,m,b1,st.copy(),depth+1)
                if rM is None: continue
                tM,stM,buM=rM
                rN=self.synth(env,n,b2,stM.copy(),depth+1)
                if rN is None: continue
                tN,stN,buN=rN
                # choose peels on tM and generalizations on tN
                for p in range(0, min(buM,self.Jmax)+1):
                    stP=stN.copy()
                    tp,pk=self.inst(tM,p,stP)
                    for g in range(0, min(buN,self.Jmax)+1):
                        stG=stP.copy()
                        tn,gens=self.generalize(tN,g,env,stG)
                        nu=stG.freshm()
                        stU=stG.copy()
                        if unify(tp, ('arr',tn,nu), stU.sub):
                            return (nu, stU, buM-p + buN-g)
            return None
        return None

    def inst(self, t, j, st):
        cnt=0
        while cnt<j:
            t=walk(t,st.sub)
            if t[0]!='all': break
            m=st.freshm()
            t=subst_tv(t[3], t[1], m, st.sub)
            cnt+=1
        return t,cnt

    def generalize(self, t, g, env, st):
        cnt=0
        # fresh rigid names, not free in env or t
        while cnt<g:
            nm=st.freshtv()[1]
            t=('all',nm,t); cnt+=1
        return t,cnt

    def typable(self, M, Bmax=6):
        for B in range(0,Bmax+1):
            self.nodes=0
            r=self.synth((), M, B, St())
            if r is not None:
                t,st,bu=r
                return t,st
        return None

if __name__=='__main__':
    def T(M,B=6):
        I=Infer()
        return I.typable(M,B)
    x0=Var(0);x1=Var(1);x2=Var(2)
    tests={
     'I':Abs(x0),'K':Abs(Abs(x1)),'xx':Abs(App(x0,x0)),
     'Omega':App(Abs(App(x0,x0)),Abs(App(x0,x0))),
     'xxI':App(Abs(App(x0,x0)),Abs(x0)),
     'S':Abs(Abs(Abs(App(App(x2,x0),App(x1,x0))))),
     'B':Abs(Abs(Abs(App(x2,App(x1,x0))))),
     'W':Abs(Abs(App(App(x1,x0),x0))),
     'Yf':Abs(App(Abs(App(x1,App(x0,x0))),Abs(App(x1,App(x0,x0))))),
    }
    for n,M in tests.items():
        r=T(M,7)
        print(n, 'TYP' if r else 'unt', tshow(r[0],r[1]) if r else '')

