def body_shapes(n, smax=3):
    leaves=[('nm',i) for i in range(n)] + [('hole',0),('hole',1)]
    bysize={1:leaves}; out=list(leaves)
    for s in range(3,smax+1,2):
        cur=[]
        for a in range(1,s-1,2):
            b=s-1-a
            if b<1 or b%2==0: continue
            for x in bysize.get(a,[]):
                for y in bysize.get(b,[]): cur.append(('arr',x,y))
        bysize[s]=cur; out.extend(cur)
    return out

def materialize(shape, names, st):
    memo={}
    def go(sh):
        if sh[0]=='nm': return ('v',names[sh[1]])
        if sh[0]=='hole':
            j=sh[1]
            if j not in memo: memo[j]=st.freshm()
            return memo[j]
        return ('arr',go(sh[1]),go(sh[2]))
    return go(shape)

