    if t[0]=='a': return d.get(t[1], t)
    return F(sub(d,t[1]), sub(d,t[2]))
def allterms(n, atommax=4):
    # all terms of size <= n over atoms 0..atommax-1
    res=[]
    for k in range(1,n+1):
        res += allterms_exact(k, atommax)
    return res
def allterms_exact(k, atommax=4):
    if k==1: return [T(a) for a in range(atommax)]
    res=[]
    for i in range(1,k-1):
        j=k-1-i
        for u in allterms_exact(i,atommax):
            for v in allterms_exact(j,atommax):
                res.append(F(u,v))
    return res

def solvable(s,t0,t1, maximg=4, atommax=4, maxphi=2):
    # enumerate phi on atoms 0..atommax-1 with images among allterms(maximg)
    imgs = allterms(maximg, atommax)
    asym = sorted(atoms(s)|atoms(t0)|atoms(t1))
    # phi must be defined on atoms appearing; enumerate images for each
    for choice in itertools.product(imgs, repeat=len(asym)):
        phi = dict(zip(asym, choice))
        B = sub(phi,s); U0=sub(phi,t0); U1=sub(phi,t1)
        if inst_matching(B,U0) and inst_matching(B,U1):
            return phi,B,U0,U1
    return None

def inst_matching(B,U):
    # exists psi with psi(B)=U. Return psi or None via structural matching.
    d={}
    def go(b,u):
        if b[0]=='a':
            if b[1] in d: return d[b[1]]==u
            d[b[1]]=u; return True
        if u[0]=='a': return False
        return go(b[1],u[1]) and go(b[2],u[2])
    return d if go(B,U) else None

