        (F(T(0),T(1)), T(2), T(3)),   # solvable
        (F(T(0),T(1)), T(0), T(1)),   # ?
        (F(T(0),T(1)), T(1), T(0)),   # ?
        (F(T(0),T(0)), T(1), T(2)),   # solvable
        (F(T(0),T(1)), F(T(2),T(3)), F(T(4),T(5))),
