from functools import lru_cache
sys.setrecursionlimit(1000000)

# Terms: ('v',n) var | ('ap',M,N) | ('l',M)
def V(n): return ('v',n)
def AP(m,n): return ('ap',m,n)
def L(m): return ('l',m)

# Types: ('v',n) | ('ar',s,t) | ('al',s)
def TV(n): return ('v',n)
def AR(s,t): return ('ar',s,t)
def AL(s): return ('al',s)

def tsize(t):
    if t[0]=='v': return 1
    if t[0]=='ar': return 1+tsize(t[1])+tsize(t[2])
    return 1+tsize(t[1])

def renS_generic(xi,t):
    # xi: funct from nat->nat ; ren_poly_type
    if t[0]=='v': return ('v',xi(t[1]))
    if t[0]=='ar': return ('ar',renS_generic(xi,t[1]),renS_generic(xi,t[2]))
    # poly_abs: scons 0 (funcomp S xi)
    newxi = lambda n: 0 if n==0 else xi(n-1)+1
    return ('al',renS_generic(newxi,t[1]))

def renS(t): return renS_generic(lambda n:n+1,t)

def subst_generic(sigma,t):
    if t[0]=='v': return sigma(t[1])
    if t[0]=='ar': return ('ar',subst_generic(sigma,t[1]),subst_generic(sigma,t[2]))
    # poly_abs: scons (poly_var 0) (funcomp (ren S) sigma)
    def newsig(n):
        if n==0: return ('v',0)
        return renS(sigma(n-1))
    return ('al',subst_generic(newsig,t[1]))

def inst_once(T,s):
    # subst_poly_type (scons T poly_var) s
    return subst_generic(lambda n: T if n==0 else ('v',n-1), s)

# universe of types
def gen_types(maxsize, nvar):
    bysize={1:[('v',i) for i in range(nvar)]}
    for n in range(2,maxsize+1):
        cur=[]
        # ar
        for k in range(1,n-1):
            j=n-1-k
            if k in bysize and j in bysize:
                for a in bysize[k]:
                    for b in bysize[j]:
                        cur.append(('ar',a,b))
        # al
        if n-1 in bysize:
            for a in bysize[n-1]:
                cur.append(('al',a))
        if cur: bysize[n]=cur
    res=[]
    for n in sorted(bysize): res.extend(bysize[n])
    return res

class Checker:
    def __init__(self, maxsize=4, nvar=3, maxdepth=60, maxsteps=2_000_000):
        self.U=gen_types(maxsize,nvar)
        self.Uset=set(self.U)
        self.maxsize=maxsize; self.nvar=nvar
        self.maxdepth=maxdepth; self.maxsteps=maxsteps
        self.steps=0
        # precompute inst transitions: from al(s) to inst_once(T,s)
        self.inst_map={}  # type t -> list of al(s) such that inst_once(T,s)=t for some T
        for u in self.U:
            if u[0]=='al':
                for T in self.U:
                    r=inst_once(T,u[1])
                    if tsize(r)<=maxsize and self.vars_ok(r):
                        self.inst_map.setdefault(r,[]).append(u)
        # also gen: t = al(renS t0)
        self.gen_map={}  # t -> list of t0 with al(renS t0)=t
        for t0 in self.U:
            g=('al',renS(t0))
            if tsize(g)<=maxsize and self.vars_ok(g):
                self.gen_map.setdefault(g,[]).append(t0)
        self.memo=set()
        self.fail=set()
    def vars_ok(self,t):
        if t[0]=='v': return t[1]<self.nvar
        if t[0]=='ar': return self.vars_ok(t[1]) and self.vars_ok(t[2])
        return self.vars_ok(t[1])
