    def var_closure(self,scheme):
        # all types reachable by inst and gen, bounded
        seen=set(); st=[scheme]; out=set()
        while st:
            u=st.pop()
            if u in seen: continue
            seen.add(u)
            if not self.size_ok(u): continue
            out.add(u)
            # inst
            if u[0]=='al':
                for T in self.U:
                    r=inst_once(T,u[1])
                    if self.size_ok(r) and r not in seen: st.append(r)
            # gen
            g=('al',renS(u))
            if self.size_ok(g) and g not in seen: st.append(g)
