        if depth<=0: return False
        key=(Gamma,M,t,depth)
        if key in self.memo: return True
        if key in self.fail: return False
        res=self._check(Gamma,M,t,depth)
        if res: self.memo.add(key)
        else: self.fail.add(key)
        return res
    def _check(self,Gamma,M,t,depth):
        if not self.size_ok(t): return False
        # gen inversion: t = al(renS t0)
        for t0 in self.gen_map.get(t,()):
            if self.check(Gamma,M,t0,depth-1): return True
        # inst inversion
        for u in self.inst_map.get(t,()):
            if self.check(Gamma,M,u,depth-1): return True
        if M[0]=='v':
            x=M[1]
            if x>=len(Gamma): return False
            return t in self.var_closure(Gamma[x])
        if M[0]=='l':
            body=M[1]
            if t[0]!='ar': return False
            s,t2=t[1],t[2]
