import itertools, sys
# terms: ('a', n) or ('f', u, v)
def size(t):
    return 1 if t[0]=='a' else 1+size(t[1])+size(t[2])
def terms(maxsize, atoms):
    bysize={0:set()}
    for k in range(1,maxsize+1):
        S=set()
        # atoms as size-1 terms
        if k==1:
            for a in atoms: S.add(('a',a))
        for i in range(1,k-1):
            j=k-1-i
            if j>=1:
                for u in bysize.get(i,set()):
                    for v in bysize.get(j,set()):
                        S.add(('f',u,v))
        bysize[k]=S
    out=set()
    for k,v in bysize.items(): out|=v
    return out
def subst(f,t):
    if t[0]=='a': return f[t[1]]
    return ('f', subst(f,t[1]), subst(f,t[2]))
def match(V,U,bind=None):
    # is U an instance of V?  exists psi, psi(V)=U. returns bool
    if bind is None: bind={}
    if V[0]=='a':
        n=V[1]
        if n in bind: return bind[n]==U
        bind[n]=U
        return True
